"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["48931"],{207191(e){e.exports=JSON.parse('{"id":7246,"title":"\u64B0\u5199\u6DF1\u5EA6\u6587\u7AE0 (\u57FA\u4E8EPSE\u6A21\u578B)","description":"\u6211\u60F3\u8BA9\u4F60\u626E\u6F14\u4E00\u540D\u8D44\u6DF1\u7684\u884C\u4E1A\u6280\u672F\u4F5C\u5BB6\uFF0C\u64C5\u957F\u5C06\u590D\u6742\u7684\u6280\u672F\u95EE\u9898\u8F6C\u5316\u4E3A\u6E05\u6670\u6613\u61C2\u7684\u89E3\u51B3\u65B9\u6848\u6587\u7AE0\u3002\\n\u4EFB\u52A1\uFF1A \u8BF7\u64B0\u5199\u4E00\u7BC7\u6DF1\u5EA6\u6587\u7AE0\u7684\u521D\u7A3F\uFF0C\u91C7\u7528\u95EE\u9898-\u65B9\u6848-\u8BC1\u636E (PSE) \u6A21\u578B\u3002\\n\u4E0A\u4E0B\u6587\uFF1A\\n\u6587\u7AE0\u4E3B\u9898\uFF1A \u89E3\u51B3 \u201C[\u586B\u5199\u75DB\u70B9\u540D\u79F0\uFF0C\u5982\uFF1AP09 - \u8BBE\u5907\u6E05\u6D17\u8017\u65F6\u8FC7\u957F]\u201D \u7684\u95EE\u9898\u3002\\n\u6211\u4EEC\u7684\u89E3\u51B3\u65B9\u6848\uFF1A \u91C7\u7528\u5728\u7EBFTOC\u5206\u6790\u4EEA\u8FDB\u884C\u5B9E\u65F6\u6E05\u6D17\u9A8C\u8BC1\u3002\\n\u5173\u952E\u8BC1\u636E/\u8BBA\u70B9\uFF1A (1) \u4F20\u7EDF\u65B9\u6CD5\uFF08\u5982HPLC\u79BB\u7EBF\u53D6\u6837\uFF09\u7684\u5F0A\u7AEF\u662F\u8017\u65F6\u3001\u6709\u5EF6\u8FDF\u3002 (2) \u5728\u7EBFTOC\u80FD\u5B9E\u65F6\u53CD\u9988\u6E05\u6D17\u6548\u679C\uFF0C\u5C06\u6E05\u6D17\u65F6\u95F4\u4ECE\u6570\u5C0F\u65F6\u7F29\u77ED\u5230\u51E0\u5341\u5206\u949F\u3002 (3) \u6211\u4EEC\u7684\u6280\u672F\u5B8C\u5168\u7B26\u5408GMP\u9644\u5F55\u4E2D\u5BF9\u6570\u636E\u5B8C\u6574\u6027\u7684\u8981\u6C42\u3002\\n\u8F93\u51FA\u683C\u5F0F\uFF1A \u8BF7\u6309\u7167\u4EE5\u4E0B\u5927\u7EB2\u7ED3\u6784\u751F\u6210\u6587\u7AE0\uFF0C\u603B\u5B57\u6570\u7EA6800\u5B57\uFF1A\\n\u5F15\u4EBA\u5165\u80DC\u7684\u6807\u9898\uFF1A\\n\u5F15\u8A00 (\u95EE\u9898Problem): \u63CF\u8FF0\u4F20\u7EDF\u6E05\u6D17\u65B9\u6CD5\u7684\u75DB\u70B9\uFF0C\u5F15\u53D1\u8BFB\u8005\u5171\u9E23\u3002\\n\u89E3\u51B3\u65B9\u6848 (Solution): \u4ECB\u7ECD\u5728\u7EBFTOC\u5206\u6790\u4EEA\u4F5C\u4E3A\u7834\u5C40\u4E4B\u9053\u3002\\n\u8BC1\u636E\u4E0E\u4F18\u52BF (Evidence): \u8BE6\u7EC6\u9610\u8FF0\u4E0A\u8FF03\u4E2A\u5173\u952E\u8BBA\u70B9\uFF0C\u53EF\u4EE5\u9002\u5F53\u5F15\u7528\u6570\u636E\u3002\\n\u7ED3\u8BBA\u4E0E\u884C\u52A8\u53F7\u53EC (CTA): \u603B\u7ED3\u65B9\u6848\u4EF7\u503C\uFF0C\u5E76\u5F15\u5BFC\u8BFB\u8005\u201C\u9884\u7EA6\u4E00\u6B21\u5728\u7EBF\u6280\u672F\u95EE\u8BCA(N06)\u201D\u3002","remark":"\u5FEB\u901F\u751F\u6210\u4E13\u4E1A\u3001\u6709\u8BF4\u670D\u529B\u7684\u6280\u672F\u6587\u7AE0\u6216\u6848\u4F8B\u5206\u6790\u3002","owner":"\u738B\u519B","upvotes":4,"downvotes":0,"upvoteDifference":4,"updatedAt":"2026-04-13T20:38:44.410Z"}')}}]);